    @Override public void onCreate(Bundle saved){setTheme(Connection.prefs(this).getBoolean("native_night",true)?R.style.NativeDark:R.style.NativePaper);super.onCreate(saved);repo=new DeviceRepository(this,this);if(saved!=null){route=saved.getString("route","home");symbol=saved.getString("symbol","");range=saved.getString("range","1D");researchSymbol=saved.getString("researchSymbol","RELIANCE.NS");search=saved.getString("search","");marketGroup=saved.getString("marketGroup","All");}theme();build();dispatchIntent();if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(0,this::goBack);}
    private void theme(){setTheme(Connection.prefs(this).getBoolean("native_night",true)?R.style.NativeDark:R.style.NativePaper);night=Connection.prefs(this).getBoolean("native_night",true);bg=color(night?"#070D1B":"#F4F5F0");surface=color(night?"#0B1425":"#FFFFFF");ink=color(night?"#E9EEFF":"#17313A");muted=color(night?"#8192B2":"#64787E");accent=color(night?"#49DEC5":"#007D76");blue=color(night?"#A2BEFF":"#365DC5");negative=color(night?"#FF9BA9":"#B63F60");edge=color(night?"#25334C":"#DDE5E0");getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(surface);if(Build.VERSION.SDK_INT>=30){getWindow().getDecorView();getWindow().setDecorFitsSystemWindows(false);if(getWindow().getInsetsController()!=null)getWindow().getInsetsController().setSystemBarsAppearance(night?0:WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);}else getWindow().getDecorView().setSystemUiVisibility(night?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}
    private int color(String v){return Color.parseColor(v);}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
    private GradientDrawable shape(int fill,int border,int radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(border!=0)d.setStroke(dp(1),border);return d;}
