    private void build(){root=vertical();root.setBackgroundColor(bg);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());android.graphics.Insets ime=i.getInsets(WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));if(nav!=null)nav.setVisibility(i.isVisible(WindowInsets.Type.ime())?View.GONE:View.VISIBLE);return WindowInsets.CONSUMED;}v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.replaceSystemWindowInsets(0,0,0,0);});root.requestApplyInsets();
        header=row();header.setPadding(dp(18),dp(8),dp(12),dp(5));TextView brand=button("↖",this::goBack);brand.setTextSize(22);brand.setBackgroundColor(Color.TRANSPARENT);header.addView(brand,new LinearLayout.LayoutParams(dp(45),dp(48)));title=text("DeckLab",23,ink,true);title.setMaxLines(1);title.setAutoSizeTextTypeUniformWithConfiguration(12,23,1,android.util.TypedValue.COMPLEX_UNIT_SP);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView refresh=button("↻",()->sync(true));refresh.setContentDescription("Refresh server data");header.addView(refresh,new LinearLayout.LayoutParams(dp(48),dp(48)));header.addView(button(night?"☀":"◐",()->{saveScroll();Connection.prefs(this).edit().putBoolean("native_night",!night).apply();theme();build();}),new LinearLayout.LayoutParams(dp(48),dp(48)));add(root,header);
        status=text("Reading saved device data…",11,muted,false);status.setPadding(dp(22),dp(4),dp(22),dp(10));add(root,status);content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));nav=row();nav.setPadding(dp(7),dp(6),dp(7),dp(6));nav.setBackgroundColor(surface);add(root,nav);render();}
    private void navigation(){nav.removeAllViews();String[][] tabs={{"home","⌂","Home"},{"markets","⌕","Markets"},{"bots","◉","Bots"},{"activity","≡","Activity"},{"more","⋯","More"}};for(String[] t:tabs){TextView b=button(t[1]+"\n"+t[2],()->go(t[0]));b.setTextSize(11);b.setPadding(dp(2),dp(6),dp(2),dp(6));b.setMaxLines(2);b.setAutoSizeTextTypeUniformWithConfiguration(8,11,1,android.util.TypedValue.COMPLEX_UNIT_SP);b.setHyphenationFrequency(android.text.Layout.HYPHENATION_FREQUENCY_NONE);b.setContentDescription(t[2]);b.setTextColor(route.equals(t[0])?accent:muted);b.setBackground(shape(route.equals(t[0])?(night?color("#263F42"):color("#E2F1E9")):surface,0,14));nav.addView(b,new LinearLayout.LayoutParams(0,dp(57),1));}}
    private void saveScroll(){if(scroll!=null)scrollPositions.put(route,scroll.getScrollY());if(list!=null)scrollPositions.put(route,list.getFirstVisiblePosition());}
    private void go(String next){if(route.equals(next))return;saveScroll();if(Arrays.asList("home","markets","bots","activity","more").contains(next)){back.clear();if(!next.equals("home"))back.push("home");}else back.push(route);route=next;render();sync(false);}
    private void render(){header.setVisibility(route.equals("home")?View.GONE:View.VISIBLE);terminalDashboard=null;labels.clear();newsContainer=null;directoryItems=null;paperText=null;archiveText=null;aiModels=null;aiStatus=null;adminText=null;adminDraft=null;chart=null;chartStatus=null;researchResult=null;researchStatus=null;researchInput=null;adapter=null;list=null;scroll=null;content.removeAllViews();title.setText(route.equals("home")?"Mission control":route.equals("detail")?symbol:route.equals("research")?"Mirai research":route.equals("admin")?"DeckLab Admin":route.substring(0,1).toUpperCase()+route.substring(1));navigation();
        if(route.equals("markets")){marketsScreen();return;}if(route.equals("bots")){botsScreen();return;}if(route.equals("activity")){activityScreen();return;}
        scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);body=vertical();body.setPadding(dp(route.equals("home")?10:20),dp(12),dp(route.equals("home")?10:20),dp(26));scroll.addView(body);content.addView(scroll,new FrameLayout.LayoutParams(-1,-1));
        switch(route){case "home":homeScreen();break;case "detail":detailScreen();break;case "research":researchScreen();break;case "settings":settingsScreen();break;case "controls":controlsScreen();break;case "news":newsScreen();break;case "alerts":alertsScreen();break;case "paper":paperScreen();break;case "archive":archiveScreen();break;case "ai":aiScreen();break;case "directory":directoryScreen();break;case "admin":adminScreen();break;default:moreScreen();}
        scroll.post(()->{if(scroll!=null)scroll.scrollTo(0,scrollPositions.getOrDefault(route,0));});updateData();}
    private void homeScreen(){
        terminalDashboard=new TerminalDashboard(this,new TerminalDashboard.Actions(){
            public void route(String next){if(next.equals("research"))researchSymbol=obj(dashboardData(),"focus").optString("symbol",researchSymbol);go(next);}
            public void focus(String selected,String bot){dashboardSymbol=selected;dashboardBot=bot;repo.fetch(dashboardPath(),0,true);updateData();}
            public void instrument(String selected){symbol=selected;go("detail");}
            public void evidence(int id){showRemote("Observed fill #"+id,"/api/population/detail?kind=fills&id="+id,"Loading the stored execution evidence…");}
        });
        add(body,terminalDashboard);terminalDashboard.bind(summary(),dashboardData());
    }
    private String dashboardPath(){return TERMINAL+(dashboardSymbol.isEmpty()&&dashboardBot.isEmpty()?"":"?symbol="+enc(dashboardSymbol)+"&bot="+enc(dashboardBot));}
    private JSONObject dashboardData(){JSONObject selected=repo.object(dashboardPath());return selected.length()>0?selected:terminal();}
    private JSONObject summary(){return repo.object(SUMMARY);}private JSONObject terminal(){return repo.object(TERMINAL);}private JSONObject obj(JSONObject a,String k){JSONObject x=a.optJSONObject(k);return x==null?new JSONObject():x;}private JSONArray arr(JSONObject a,String k){JSONArray x=a.optJSONArray(k);return x==null?new JSONArray():x;}
    private String statusResource(){if(route.equals("directory"))return directoryPath();if(route.equals("news")||route.equals("alerts"))return STATE;if(route.equals("detail"))return chartPath();if(route.equals("markets")||route.equals("paper"))return STATE;if(route.equals("research"))return TERMINAL;if(route.equals("activity"))return journalPath();if(route.equals("archive"))return "/api/demo?view=summary";if(route.equals("ai"))return "/api/ai-settings";return SUMMARY;}
    private boolean ownerPauseVeto(){return repo.ownerPauseVeto();}
    private boolean ownerPaused(){return repo.health(READINESS).fresh(System.currentTimeMillis(),60000)&&ownerPauseVeto();}
    private void updateData(){if(content==null)return;String resource=statusResource();ResourceHealth.Snapshot health=repo.health(resource);long stamp=repo.received(resource);boolean fresh=health.fresh(System.currentTimeMillis(),45000);boolean paused=ownerPaused();String pause=paused?"OWNER PAUSE ACTIVE · ":"Owner pause unknown · ";String state=fresh?"Server reachable for "+route:health.error!=null?"Resource unavailable":"Resource not verified this session";status.setText(pause+state+" · saved "+date(stamp)+" · quote source times remain authoritative");status.setTextColor(health.error!=null||paused?negative:muted);
        if(route.equals("home")&&terminalDashboard!=null)terminalDashboard.bind(summary(),dashboardData());
        if(route.equals("markets"))updateMarkets();if(route.equals("bots"))updateBots();if(route.equals("activity"))updateActivity();if(route.equals("detail"))updateDetail();if(route.equals("research"))updateResearch();if(route.equals("news"))updateNews();if(route.equals("archive"))updateArchive();if(route.equals("paper"))updatePaper();if(route.equals("ai"))updateAI();if(route.equals("directory"))updateDirectory();}
    private void sync(boolean force){if(!resumed)return;repo.fetch(READINESS,30000,force);repo.fetch(SUMMARY,5000,force);repo.fetch(TERMINAL,15000,force);if(route.equals("home")&&!dashboardPath().equals(TERMINAL))repo.fetch(dashboardPath(),15000,force);repo.fetch(STATE,60000,force);if(route.equals("detail"))repo.fetch(chartPath(),60000,force);if(route.equals("activity"))repo.fetch(journalPath(),10000,force);if(route.equals("archive"))repo.fetch("/api/demo?view=summary",15000,force);if(route.equals("ai")){repo.fetch("/api/ai-settings",30000,force);repo.fetch("/api/ai-models",900000,force);}if(route.equals("directory"))repo.fetch(directoryPath(),30000,force);}
    @Override public void changed(String path,boolean success,String error){if(!resumed)return;if(path.equals(pendingDetailPath)&&remoteDetail!=null){remoteDetail.setText(success?readable(repo.object(path)):"Saved detail unavailable · "+error);}if(success&&path.equals(SUMMARY)&&route.equals("controls")&&!renderedControls.equals(obj(summary(),"settings").toString())){render();return;}updateData();if(!success&&route.equals("detail")&&path.equals(chartPath())&&chartStatus!=null)chartStatus.setText("Saved chart / provider unavailable · "+error);}
    private void listLayout(String description){LinearLayout box=vertical();box.setPadding(dp(20),dp(10),dp(20),0);add(box,text(description,13,muted,false));space(box,14);list=new ListView(this);list.setDivider(null);list.setSelector(shape(night?color("#263F42"):color("#E2F1E9"),0,14));list.setClipToPadding(false);list.setPadding(0,0,0,dp(15));list.setEmptyView(null);adapter=new Rows();list.setAdapter(adapter);box.addView(list,new LinearLayout.LayoutParams(-1,0,1));content.addView(box,new FrameLayout.LayoutParams(-1,-1));list.setSelection(scrollPositions.getOrDefault(route,0));}
    private void marketsScreen(){LinearLayout box=vertical();box.setPadding(dp(20),dp(8),dp(20),0);EditText input=edit("Search saved symbols or companies",search);add(box,input);space(box,10);HorizontalScrollView chips=new HorizontalScrollView(this);chips.setHorizontalScrollBarEnabled(false);LinearLayout row=row();for(String g:new String[]{"All","Saved","India","Stocks","Crypto","Forex","Gold"}){TextView b=button(g,()->{marketGroup=g;updateMarkets();});b.setTextColor(g.equals(marketGroup)?accent:muted);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(44));lp.rightMargin=dp(6);row.addView(b,lp);}chips.addView(row);add(box,chips);space(box,8);label(box,"marketCount","Device library",11,muted,false);space(box,8);list=new ListView(this);list.setDivider(null);list.setClipToPadding(false);list.setPadding(0,0,0,dp(16));adapter=new Rows();list.setAdapter(adapter);box.addView(list,new LinearLayout.LayoutParams(-1,0,1));content.addView(box,new FrameLayout.LayoutParams(-1,-1));watch(input,()->{search=input.getText().toString();updateMarkets();});updateMarkets();}
    private void updateMarkets(){if(adapter==null)return;JSONArray a=repo.store.instruments(repo.origin(),search,marketGroup,marketGroup.equals("Saved"));set("marketCount",a.length()+" matches · "+marketGroup+" · stored on this device");adapter.show(a,"market");list.setOnItemClickListener((p,v,pos,id)->{JSONObject item=adapter.items.optJSONObject(pos);if(item!=null){symbol=item.optString("symbol");go("detail");}});}
    private void botsScreen(){listLayout("Your saved bot balances, holdings and recorded ratings.");updateBots();}
    private void updateBots(){if(adapter==null)return;adapter.show(arr(summary(),"bots"),"bot");list.setOnItemClickListener((p,v,pos,id)->{JSONObject a=adapter.items.optJSONObject(pos);if(a!=null)showBot(a);});}
    private void showBot(JSONObject b){LinearLayout p=vertical();p.setPadding(dp(20),dp(14),dp(20),dp(20));add(p,text(money(b,"equity_usd","USD"),29,ink,true));add(p,text("Funded "+money(b,"initial","USD")+" · P&L "+money(b,"pnl_usd","USD"),13,muted,false));JSONObject population=obj(b,"population"),r=obj(population,"ai_route");add(p,text(r.optString("model",population.optString("model"))+" · "+b.optInt("points")+" points",14,accent,true));space(p,13);add(p,text("Positions",18,ink,true));JSONArray positions=arr(b,"positions");for(int i=0;i<positions.length();i++){JSONObject x=positions.optJSONObject(i);if(x!=null)add(p,button(x.optString("symbol")+" · "+fmt(x.optDouble("qty"),8)+" units",()->{symbol=x.optString("symbol");go("detail");}));}if(positions.length()==0)add(p,text("No saved positions.",14,muted,false));space(p,14);add(p,text("Recorded review",16,ink,true));add(p,text(population.optString("score_reason","No saved reviewer explanation."),13,muted,false));showPanel(b.optString("bot"),p);}
    private void activityScreen(){listLayout("Complete stored journal pages. Tap a record for evidence.");LinearLayout parent=(LinearLayout)list.getParent();LinearLayout tools=row();Spinner picker=spinner(new String[]{"fills","orders","outcomes","decisions","learning","activity"},activityKind);tools.addView(picker,new LinearLayout.LayoutParams(0,dp(48),1));tools.addView(button("‹",()->{if(activityPage>0){activityPage--;updateActivity();repo.fetch(journalPath(),0,true);}}));tools.addView(button("›",()->{activityPage++;updateActivity();repo.fetch(journalPath(),0,true);}));parent.addView(tools,1);picker.setOnItemSelectedListener(selectedListener(pos->{String next=picker.getSelectedItem().toString();if(!activityKind.equals(next)){activityKind=next;activityPage=0;updateActivity();repo.fetch(journalPath(),0,true);}}));updateActivity();}
    private void updateActivity(){if(adapter==null)return;JSONObject journal=obj(repo.object(journalPath()),"journal");adapter.show(arr(journal,"items"),activityKind);list.setOnItemClickListener((p,v,pos,id)->{JSONObject x=adapter.items.optJSONObject(pos);if(x!=null)showEvidence(x);});}
    private String pendingDetailPath;private TextView remoteDetail;private AlertDialog remoteDialog;
    private void showEvidence(JSONObject a){String kind=activityKind;String id=a.optString("id",a.optString("episode"));if(!Arrays.asList("fills","orders","decisions").contains(kind)||id.isEmpty()){showText("Record",readable(a));return;}String path="/api/population/detail?kind="+kind+"&id="+enc(id);showRemote("Recorded "+kind+" #"+id,path,readable(a));}
    private void detailScreen(){JSONObject a=instrument(symbol);LinearLayout c=card(body);add(c,text(a.optString("name",symbol),14,muted,false));space(c,10);label(c,"assetPrice",money(a,"price",a.optString("currency","USD")),32,ink,true);label(c,"assetSource",source(a),12,muted,false);space(c,14);JSONObject item=repo.store.item(repo.origin(),symbol);add(c,button(item.optBoolean("pinned")?"★ Saved on this phone":"☆ Save on this phone",()->{repo.store.updateItem(repo.origin(),symbol,!repo.store.item(repo.origin(),symbol).optBoolean("pinned"),null);render();}));
        c=card(body);LinearLayout choices=row();for(String span:new String[]{"1D","1W","1M"}){TextView b=button(span,()->{range=span;updateDetail();repo.fetch(chartPath(),0,true);});choices.addView(b,new LinearLayout.LayoutParams(0,dp(45),1));}add(c,choices);space(c,10);chart=new NativeChart(this);chart.colors(ink,muted,accent,negative,edge);c.addView(chart,new LinearLayout.LayoutParams(-1,dp(260)));chartStatus=text("Reading saved provider candles…",11,muted,false);add(c,chartStatus);add(c,button("Reset zoom",()->chart.fit()));
        c=card(body);section(c,"Your device note");EditText note=edit("What are you watching?",item.optString("note"));note.setMinLines(3);note.setGravity(Gravity.TOP);add(c,note);space(c,10);add(c,button("Save note offline",()->{repo.store.updateItem(repo.origin(),symbol,null,note.getText().toString());toast("Saved in this app’s private database");}));
        c=card(body);add(c,button("✳  Ask Mirai about "+symbol,()->{researchSymbol=symbol;go("research");}));space(c,8);add(c,button("Create server price alert",this::createAlert));space(c,8);add(c,button("Original paper account · order preview",this::paperOrder));updateDetail();repo.fetch(chartPath(),60000,false);}
    private void updateDetail(){JSONObject a=instrument(symbol);set("assetPrice",money(a,"price",a.optString("currency","USD")));set("assetSource",source(a));JSONArray bars=repo.array(chartPath());if(chart!=null)chart.data(bars,true,a.optString("currency","USD"));if(chartStatus!=null)chartStatus.setText(bars.length()>0?bars.length()+" saved provider candles · "+range+" · drag to inspect / pinch to zoom\nSnapshot "+date(repo.received(chartPath())):"No saved candles for "+range+". A server connection is needed to fetch them.");}
    private JSONObject instrument(String s){JSONArray a=repo.store.instruments(repo.origin(),s,"All",false);for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&s.equals(x.optString("symbol")))return x;}return new JSONObject();}
    private void researchScreen(){LinearLayout c=card(body);section(c,"A native desk for Mirai");add(c,text("Dated public market context. Replies never execute orders.",13,muted,false));space(c,12);EditText focus=edit("Symbol",researchSymbol);add(c,focus);researchInput=edit("Ask a question about this market",repo.store.draft(repo.origin(),"research"));researchInput.setMinLines(3);researchInput.setGravity(Gravity.TOP);add(c,researchInput);watch(researchInput,()->{repo.store.draft(repo.origin(),"research",researchInput.getText().toString());requestId=null;});watch(focus,()->{researchSymbol=focus.getText().toString().trim();requestId=null;});space(c,12);add(c,button("Ask Mirai →",()->askMirai()));researchStatus=text("Uses your privately saved Mirai connection",12,accent,false);add(c,researchStatus);c=card(body);researchResult=text("Your saved replies appear here, including when offline.",14,ink,false);researchResult.setTextIsSelectable(true);add(c,researchResult);updateResearch();}
    private void askMirai(){if(sending)return;if(!online()){toast("Connect to the server to request a new Mirai reply. Saved replies remain available.");return;}String topic=researchInput.getText().toString().trim();if(topic.isEmpty())topic="Explain current observed conditions, source freshness and what evidence to watch next.";if(requestId==null)requestId=UUID.randomUUID().toString();JSONObject body=json("symbol",researchSymbol,"topic",topic,"request_id",requestId);sending=true;researchStatus.setText("Submitting to Mirai…");repo.post("/api/terminal/research",body,(r,e)->{sending=false;if(r==null){if(researchStatus!=null)researchStatus.setText(e+" · retry retains the same request ID");return;}requestId=null;if(researchStatus!=null)researchStatus.setText("Mirai is reading the public snapshot…");repo.fetch(TERMINAL,0,true);});}
    private void updateResearch(){if(researchResult==null)return;JSONArray a=arr(terminal(),"briefs");StringBuilder result=new StringBuilder();boolean running=false;for(int i=0;i<a.length();i++){JSONObject b=a.optJSONObject(i);if(b==null)continue;result.append(b.optString("symbol")).append("  ·  ").append(b.optString("model")).append("\n").append(b.optString("state")).append(" · ").append(date((long)(b.optDouble("created")*1000))).append("\n\n").append(b.optString("state").equals("completed")?b.optString("body"):b.optString("error",b.optString("body"))).append("\n\n────────────\n\n");if(b.optString("state").equals("running"))running=true;}
        if(a.length()>0)researchResult.setText(result.toString());if(researchStatus!=null&&!sending)researchStatus.setText(running?"Mirai is researching · you can leave this screen":obj(terminal(),"mirai").optBoolean("key_configured")?"Mirai configured · replies saved on server and device":"Set up Mirai in More → AI connection");if(running)repo.fetch(TERMINAL,3000,false);}
